xpath.script:
(function () {
  /* La franja «Showroom» (mandar al muro) es fija abajo, pero vive dentro de #product_details, que es
     sticky y crea su propio contexto de apilado: la galería la tapaba. Se cuelga directo de <body>. */
  function liftBar() {
    document.querySelectorAll('#product_detail .o_showroom_bar, #product_details .o_showroom_bar').forEach(function (b) { document.body.appendChild(b); });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', liftBar); else liftBar();
})();
(function () {
  /* El video 360° del anillo vive en la descripción. Se muestra arriba de la galería, a todo el ancho,
     y al hacer clic se abre en grande (como el zoom de las fotos). */
  /* «Pregunta por WhatsApp»: mismo mensaje que el botón flotante (anillo + metal elegido + liga) */
  var ask = document.querySelector('.anbn-wa-ask');
  if (ask) ask.addEventListener('click', function () {
    var h1 = document.querySelector('#product_details h1');
    var metal = document.querySelector('.js_main_product input[data-attribute-name="Metal"]:checked');
    var med = document.querySelector('.js_main_product input[data-attribute-name="Medida"]:checked');
    var msg = 'Hola Anello, tengo una pregunta sobre el anillo «' + (h1 ? h1.textContent.trim() : '') + '»'
            + (metal ? ' en ' + metal.dataset.valueName : '') + (med ? ', medida ' + med.dataset.valueName.replace(/\.0$/, '') : '')
            + ': ' + location.origin + location.pathname;
    ask.href = 'https://wa.me/524433244511?text=' + encodeURIComponent(msg);
    if (window.anbnWaBeacon) window.anbnWaBeacon('product');
  });
  var src = document.querySelector('#product_details .o_anello_video video');
  if (!src) return;
  var url = src.getAttribute('src');
  src.closest('.o_anello_video').style.display = 'none';
  function open() {
    var o = document.createElement('div');
    o.className = 'anbn-vbox';
    o.innerHTML = '<button type="button" aria-label="Cerrar">&times;</button><video controls autoplay muted loop playsinline></video>';
    o.querySelector('video').src = url;
    function close() { o.remove(); document.removeEventListener('keydown', esc); }
    function esc(e) { if (e.key === 'Escape') close(); }
    o.addEventListener('click', function (e) { if (e.target === o || e.target.tagName === 'BUTTON') close(); });
    document.addEventListener('keydown', esc);
    document.body.appendChild(o);
  }
  function place() {
    var g = document.querySelector('.o_wsale_product_images');
    if (!g || g.querySelector('.anbn-video')) return;
    var w = document.createElement('div');
    w.className = 'anbn-video';
    w.setAttribute('role', 'button');
    w.setAttribute('aria-label', 'Ver video 360° en grande');
    w.innerHTML = '<video autoplay muted loop playsinline preload="metadata"></video><span>360°</span><i class="fa fa-expand"></i>';
    w.querySelector('video').src = url;
    w.addEventListener('click', open);
    g.insertBefore(w, g.firstChild);
  }
  place();
  var g = document.querySelector('.o_wsale_product_images');
  if (g) new MutationObserver(place).observe(g, { childList: true, subtree: true });
})();
